// NLE-001: Broken image on /
// Generated by Nomad Loop Engine. Run: npx playwright test nle-001.spec.ts
import { test, expect } from '@playwright/test';

test("NLE-001: Broken image on /", async ({ page }) => {
  const errors: string[] = [];
  const failed: string[] = [];
  const docStatuses: number[] = [];
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('response', (res) => {
    if (res.request().isNavigationRequest()) docStatuses.push(res.status());
    else if (res.status() >= 400) failed.push(`${res.status()} ${res.url()}`);
  });
  await page.goto("http://localhost:4100");
  expect(failed).toEqual([]);
});

